//! Programs compiled by the pinned FTEQCC (fte-team/fteqw@f937b9d88f71fc4429db5fe56c6a98d922711b2e)
//! and its diagnostics for each, which the FTEQCC profile reports alike (2026-10-28).

use std::path::PathBuf;

use qc_preproc::CommandLine;
use qc_syntax::Dialect;

use crate::db::Db;
use crate::expand::ModuleInput;
use crate::symbol::FileId;

/// Every diagnostic message of the FTEQCC file `source`, in order.
fn messages(source: &str) -> Vec<String> {
    let mut db = Db::new();
    db.set_dialect(Dialect::Fteqcc);
    db.set_file(
        FileId(0),
        PathBuf::from("t.qc"),
        format!("{source}\n").into_bytes(),
    );
    let analysis = db.analyze_module(&ModuleInput {
        compiled: vec![FileId(0)],
        command_line: CommandLine::new::<&str>(&[]),
        ..ModuleInput::default()
    });
    analysis
        .diagnostics()
        .map(|d| d.diagnostic.message.clone())
        .collect()
}

/// Each case's program: its prelude, by its index in [`PRELUDES`], and its last line.
fn check(cases: &[(usize, &str, &[&str])]) {
    for &(prelude, last, expected) in cases {
        let source = format!("{}\n{last}", PRELUDES[prelude]);
        assert_eq!(messages(&source), expected, "{source}");
    }
}

// spec FTEF-34.1: a statement is checked as `QCC_PR_ParseStatement` checks it
// spec FTEF-34.3: a switch's cases are checked against its operand
// spec FTEF-30.2: a condition is tested as `QCC_Generate_OP_IFNOT` tests it
#[test]
fn statements_are_reported_as_fteqcc_reports_them() {
    check(STATEMENTS);
}

// spec FTEF-30.4: `-e`, `++e` and `--e` of each type
// spec FTEF-30.5: `*e` of each type
#[test]
fn terms_are_reported_as_fteqcc_reports_them() {
    check(TERMS);
}

// spec FTEF-30.1: a test of a value of each type
// spec FTEF-30.7: a vector constructor of each type
// spec FTEF-30.8: a cast between each pair of types
#[test]
fn unary_and_casts_are_reported_as_fteqcc_reports_them() {
    check(UNARY_AND_CASTS);
}

// spec FTEF-30.5: under `qccx` a float or integer dereferenced is an entity; under `qcfuncs` a
// function is no pointer
#[test]
fn qccx_and_qcfuncs_are_reported_as_fteqcc_reports_them() {
    check(QCCX_AND_QCFUNCS);
}

// spec FTEF-29.7: a store checks its value's type against the target's by `typecmp_lax`
// spec FTEF-28.2: a comparison's operands of types `typecmp_lax` tells apart warn
#[test]
fn assignments_are_reported_as_fteqcc_reports_them() {
    check(ASSIGNMENTS);
}

// spec FTEF-2.8: a registered type name is a type, any other word is not
#[test]
fn c_type_words_are_reported_as_fteqcc_reports_them() {
    check(C_TYPE_WORDS);
}

// spec FTEF-27.2: an opcode the target lacks is emulated
// spec FTEF-34.9: a statement at global scope cannot be generated
#[test]
fn emulations_are_reported_as_fteqcc_reports_them() {
    check(EMULATIONS);
}

